      winter_owl: `${DEF(LG("w1-ow-g", "#FFFFFF", "#D8E4F4"))}<path d="M16 21l0-11 8.5 6zM48 21l0-11-8.5 6z" fill="#EEF4FC" ${SO}/><path d="M13 29c0-12 8-20 19-20s19 8 19 20v11c0 11-8 17-19 17s-19-6-19-17z" fill="url(#w1-ow-g)" ${SO}/><path d="M15 36c-1 8 2 14 8 17-3-6-4-11-3-16zM49 36c1 8-2 14-8 17 3-6 4-11 3-16z" fill="#C9D8EC"/><circle cx="24.5" cy="26" r="6" fill="#FFD23F" ${SOw(2)}/><circle cx="39.5" cy="26" r="6" fill="#FFD23F" ${SOw(2)}/><circle cx="25" cy="26.5" r="3" fill="${D}"/><circle cx="39" cy="26.5" r="3" fill="${D}"/><circle cx="26" cy="25.3" r="1" fill="#fff"/><circle cx="40" cy="25.3" r="1" fill="#fff"/><path d="M29.5 31l2.5 4.5 2.5-4.5z" fill="#4A5670" ${SOw(1.4)}/><path d="M23 41l2.5 1.8 2.5-1.8M36 41l2.5 1.8 2.5-1.8M29.5 46l2.5 1.8 2.5-1.8M24 50l2.5 1.8 2.5-1.8M35 50l2.5 1.8 2.5-1.8" fill="none" stroke="#6F8FC0" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round"/><rect x="3" y="54" width="58" height="7" rx="3.5" fill="#8A6043" ${SO}/><path d="M6 55.5c2-4 7-4 9-1 2-3 6-3 8 0M41 55c2-3.5 7-3.5 9-.5 2-3 6-3 9 .5" fill="#fff" ${SOw(1.8)}/><ellipse cx="26" cy="56" rx="3.2" ry="2" fill="#8A97AB"/><ellipse cx="38" cy="56" rx="3.2" ry="2" fill="#8A97AB"/>${BLUSH(18, 46, 34)}`,
